def transform(grid):
    """Copy the three-cell horizontal 9 motif onto each 2 marker, centered on it."""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [row[:] for row in grid]
    # The prototype is a contiguous horizontal run of three 9s.
    proto = None
    for r in range(h):
        for c in range(w - 2):
            if grid[r][c:c+3] == [9, 9, 9]:
                proto = [(0, -1, 9), (0, 0, 9), (0, 1, 9)]
                break
        if proto:
            break
    if proto is None:
        return out
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                for dr, dc, color in proto:
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
    return out

